mutation SetStaticRoutes($id: String!, $routes: [StaticRouteInput]) {
  setStaticRoutes(id: $id, routes: $routes) {
    id
    routes {
      type
      source
      destination
      __typename
    }
    __typename
  }
}

mutation SetStaticHeaders($id: String!, $headers: [StaticHeaderInput]) {
  setStaticHeaders(id: $id, headers: $headers) {
    id
    headers {
      path
      name
      value
      __typename
    }
    __typename
  }
}

